interface ScoreCardProps {
  score: number
}

function getScoreColor(score: number): string {
  if (score >= 70) return 'text-accent'
  if (score >= 40) return 'text-amber-500'
  return 'text-red-500'
}

function getScoreLabel(score: number): string {
  if (score >= 70) return 'Strong profile'
  if (score >= 40) return 'Needs improvement'
  return 'Weak profile'
}

export function ScoreCard({ score }: ScoreCardProps) {
  const color = getScoreColor(score)
  const label = getScoreLabel(score)
  const circumference = 2 * Math.PI * 36
  const offset = circumference - (score / 100) * circumference

  return (
    <div className="bg-white rounded-xl border border-slate-200 p-6">
      <div className="flex items-center gap-6">
        {/* Circular progress */}
        <div className="relative shrink-0">
          <svg width="80" height="80" viewBox="0 0 80 80" className="-rotate-90">
            <circle
              cx="40" cy="40" r="36"
              fill="none"
              stroke="#e2e8f0"
              strokeWidth="8"
            />
            <circle
              cx="40" cy="40" r="36"
              fill="none"
              stroke="currentColor"
              strokeWidth="8"
              strokeLinecap="round"
              strokeDasharray={circumference}
              strokeDashoffset={offset}
              className={color}
            />
          </svg>
          <span className={`absolute inset-0 flex items-center justify-center text-xl font-bold ${color}`}>
            {score}
          </span>
        </div>

        <div>
          <p className="text-lg font-semibold text-slate-900">{label}</p>
          <p className="text-sm text-slate-500 mt-1">
            Your profile scored {score} out of 100. {score < 70 ? 'See the issues below and upgrade to get the full rewrite.' : 'Upgrade to get your AI-powered rewrite.'}
          </p>
        </div>
      </div>
    </div>
  )
}
